mapper.select:
SELECT s.*, e.AVATAR AS providerAvatar, e.EXTENSION_NAME AS extensionName, e.TYPE AS extensionType FROM `AI_VEC_SOURCE` s LEFT JOIN `SYS_EXTENSION` e ON s.EXTENSION_CODE = e.EXTENSION_CODE AND e.DELETED = 0 WHERE s.DELETED = 0
AND s.NAME LIKE CONCAT('%', #{req.name}, '%')
AND s.EXTENSION_CODE = #{req.extensionCode}
AND s.STATUS = #{req.status}
AND s.ENV_CODE = #{req.envCode}
AND s.CREATE_USER = #{req.createUser}
ORDER BY s.CREATE_TIME DESC
